/* selectCmnFileList - Lee JiSeob */
SELECT ATFINO, MNG_SN, ATCMFL_CL_NM, REAL_FILE_NM, STRG_FILE_NM, STRG_COURS_NM, FILE_EXTN_NM, FILE_SZ, FILE_STTS_SE_CD, FRST_RGTR_ID, FRST_REG_DT, LAST_MDFR_ID, LAST_MDFCN_DT
FROM SAB821
WHERE ATFINO = #{ATFINO}
AND ATCMFL_CL_NM = #{ATCMFL_CL_NM}
AND MNG_SN = #{MNG_SN}
AND FILE_STTS_SE_CD = 'N'
ORDER BY MNG_SN

